def render_pet_world_html(ui_locale='en', appearance=None):
    locale = catalog_for(ui_locale).locale
    spec = get_locale(locale)
    direction = spec.direction if spec else 'ltr'
    return ('<!doctype html><html lang="'+html.escape(locale)+'" dir="'+direction+'"'+appearance_html_attrs(appearance)+' data-vool-motion="off"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>'+html.escape(catalog_for(locale).text('yard.title'))+'</title><style>'+DARK_PALETTE_CSS+LIGHT_PALETTE_CSS+CSS+font_css()+governor_css()+'</style>'+current_skin_style()+render_i18n_bootstrap(locale)+'</head><body><div id="main" class="tb-root">'+MARKUP+render_world_controls(locale)+'</div>'+render_pet_cosmetics_fragment()+'<script>'+APPEARANCE_JS+COMPANION_WORLD_JS+LIFEFORM_ART_JS+PET_WORLD_RENDER_JS+PET_WORLD_PETS_JS+JS+WORLD_JS+'</script></body></html>')


